void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float scale = 2.0;
    vec2 uv = scale * (2.0 * fragCoord - iResolution.xy) / iResolution.y;
    uv+=iTime*0.5;
    vec3 col = vec3(1.0);

    // Tamaño del tile
    float tileSize = 1.0;

    // Posición del tile
    vec2 tilePos = floor(uv / tileSize);
    vec2 localPos = fract(uv / tileSize) * tileSize;

    // Alternar entre figuras normales y rotadas
    if (mod(tilePos.x + tilePos.y, 2.0) < 1.0) {
        // Tile normal
        col = figura(localPos, col);
    } else {
        // Tile rotado 180 grados
        vec2 rotatedPos = rotate(localPos - 0.5 * tileSize, PI) + 0.5 * tileSize;
        col = figura(rotatedPos, col);
    }

       if (iMouse.z>0.) col *= .6 + .6 * cos( 6.3*random(tilePos)  + vec3(0,23,21)  ); // hue

    col = pow(col, vec3(0.554545));
    fragColor = vec4(col, 1.0);
}

